	white-space: nowrap;
	box-shadow: 0 2px 6px rgba(239, 68, 68, 0.4);
}

/* Guide Lines */
.timeline-guide-marker[data-v-48ebc23b] {
	position: absolute;
	top: 0;
	bottom: 0;
	z-index: 6;
	pointer-events: none;
}
.timeline-guide-line[data-v-48ebc23b] {
	width: 2px;
	height: 100%;
}
.timeline-guide-line--min-start[data-v-48ebc23b] {
	border-left: 2px dashed #7c3aed;
	opacity: 0.7;
}
.timeline-guide-line--desired-start[data-v-48ebc23b] {
	border-left: 2px dashed #4f46e5;
	opacity: 0.7;
}
.timeline-guide-line--actual-start[data-v-48ebc23b] {
	border-left: 2px dashed #059669;
	opacity: 0.8;
}

