	background: var(--color-main-background);
	color: var(--color-main-text);
	padding: 0 12px;
	font-size: 14px;
}
.form-field--checkbox[data-v-48ebc23b] {
	display: flex;
	align-items: flex-end;
}
.form-checkbox[data-v-48ebc23b] {
	display: inline-flex;
	align-items: center;
	gap: 10px;
	height: 44px;
	padding: 0 10px;
	border: 1px solid var(--color-border);
	border-radius: var(--border-radius-large);
	background: var(--color-main-background);
}
.form-checkbox input[data-v-48ebc23b] {
	width: 16px;
	height: 16px;
}
.form-label[data-v-48ebc23b] {
	display: block;
	font-size: 13px;
	font-weight: 700;
	margin-bottom: 8px;
	color: var(--color-text-maxcontrast);
}
.form-row[data-v-48ebc23b] {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 16px;
}
.color-grid[data-v-48ebc23b] {
	display: flex;
	gap: 10px;
	flex-wrap: wrap;
}
.color-swatch[data-v-48ebc23b] {
	width: 36px;
	height: 36px;
	border-radius: 10px;
	border: 2px solid transparent;
	cursor: pointer;
	transition: transform 0.2s ease;
}
.color-swatch[data-v-48ebc23b]:hover {
	transform: scale(1.1);
}
.color-swatch.active[data-v-48ebc23b] {
	border-color: var(--color-main-text);
	box-shadow: 0 0 0 2px var(--color-main-background), 0 0 0 4px var(--color-primary-element);
}
.phase-form__footer[data-v-48ebc23b] {
	margin-top: 32px;
	display: flex;
	justify-content: flex-end;
	gap: 12px;
}
@media (max-width: 900px) {
.gantt-v2[data-v-48ebc23b], .gantt-v2--admin[data-v-48ebc23b] {
