		border-right: none;
}
.gantt-v2__status[data-v-48ebc23b] {
		width: 100%;
		max-width: 100%;
		border-left: none;
}
.gantt-v2__actions[data-v-48ebc23b] {
		width: 100%;
		max-width: 100%;
		border-left: none;
}
