	box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
	border: 2px solid #fff;
	z-index: 8;
	transition: transform 0.2s ease;
}

.today-marker {
	position: absolute;
	top: 0;
	bottom: 0;
	z-index: 15;
	pointer-events: none;
}

.today-line {
	width: 2px;
	height: 100%;
	background: #ef4444;
	box-shadow: 0 0 8px rgba(239, 68, 68, 0.4);
	position: relative;
}

.today-line::before {
	content: '';
	position: absolute;
	top: 0;
	left: 50%;
	transform: translateX(-50%);
	width: 8px;
	height: 8px;
	background: #ef4444;
	border-radius: 50%;
	box-shadow: 0 0 8px rgba(239, 68, 68, 0.6);
}

.today-badge {
	position: absolute;
	top: 12px;
	left: 50%;
	transform: translateX(-50%);
	background: #ef4444;
	color: #fff;
	font-size: 10px;
	font-weight: 800;
	text-transform: uppercase;
	padding: 3px 8px;
	border-radius: 12px;
	white-space: nowrap;
	box-shadow: 0 2px 6px rgba(239, 68, 68, 0.4);
}

/* Guide Lines */
.timeline-guide-marker {
	position: absolute;
	top: 0;
	bottom: 0;
	z-index: 6;
	pointer-events: none;
}

.timeline-guide-line {
	width: 2px;
	height: 100%;
}

.timeline-guide-line--min-start {
	border-left: 2px dashed #7c3aed;
	opacity: 0.7;
}

.timeline-guide-line--desired-start {
	border-left: 2px dashed #4f46e5;
	opacity: 0.7;
}

.timeline-guide-line--actual-start {
	border-left: 2px dashed #059669;
	opacity: 0.8;
}

/* Column 3: Status Column */
.gantt-v2__status {
	border-left: 1px solid var(--color-border);
	background: var(--color-main-background);
}

.status-row {
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 0 10px;
	border-bottom: 1px solid var(--color-border);
	box-sizing: border-box;
}

.status-row--system-planning {
	height: 76px;
	background: rgba(59, 130, 246, 0.03);
}

.status-row--phase-header {
	background: var(--color-background-hover);
}

.status-pill {
	display: inline-flex;
	align-items: center;
	gap: 4px;
	padding: 2px 6px;
	border-radius: 99px;
	font-size: 10px;
	font-weight: 700;
	border: 1px solid transparent;
	white-space: nowrap;
}

.status-dot {
