	transition: all 0.2s ease;
}

.phase-chip:hover {
	border-color: var(--phase-color);
	background: var(--color-background-hover);
}

/* Phase Form / Modal */
.phase-form {
	padding: 32px;
}

.phase-form__header {
	margin-bottom: 24px;
}

.phase-form__header h3 {
	margin: 0;
	font-size: 22px;
}

.phase-form__header p {
	margin: 4px 0 0;
	color: var(--color-text-maxcontrast);
}

.phase-form__content {
	display: flex;
	flex-direction: column;
	gap: 20px;
}

.form-select {
	width: 100%;
	height: 44px;
	border-radius: var(--border-radius-large);
	border: 1px solid var(--color-border);
	background: var(--color-main-background);
	color: var(--color-main-text);
	padding: 0 12px;
	font-size: 14px;
}

.form-field--checkbox {
	display: flex;
	align-items: flex-end;
}

.form-checkbox {
	display: inline-flex;
	align-items: center;
	gap: 10px;
	height: 44px;
	padding: 0 10px;
	border: 1px solid var(--color-border);
	border-radius: var(--border-radius-large);
	background: var(--color-main-background);
}

.form-checkbox input {
	width: 16px;
	height: 16px;
}

.form-label {
	display: block;
	font-size: 13px;
	font-weight: 700;
	margin-bottom: 8px;
	color: var(--color-text-maxcontrast);
}

.form-row {
	display: grid;
	grid-template-columns: 1fr 1fr;
	gap: 16px;
}

.color-grid {
	display: flex;
	gap: 10px;
	flex-wrap: wrap;
}

.color-swatch {
	width: 36px;
	height: 36px;
	border-radius: 10px;
	border: 2px solid transparent;
	cursor: pointer;
	transition: transform 0.2s ease;
}

.color-swatch:hover {
	transform: scale(1.1);
}

.color-swatch.active {
	border-color: var(--color-main-text);
	box-shadow: 0 0 0 2px var(--color-main-background), 0 0 0 4px var(--color-primary-element);
}

.phase-form__footer {
	margin-top: 32px;
	display: flex;
	justify-content: flex-end;
	gap: 12px;
}

@media (max-width: 900px) {
	.gantt-v2, .gantt-v2--admin {
		grid-template-columns: minmax(0, 1fr);
	}
	.gantt-v2__sidebar {
		width: 100%;
